51	<body>
52	<main>
53	  <h1>Todos</h1>
54	  <form id="add-form">
55	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
56	    <button data-testid="todo-add" type="submit">Add</button>
57	  </form>
58	  <ul data-testid="todo-list"></ul>
59	</main>
60	<script>
61	(function () {
62	  var STORAGE_KEY = 'todos';
63	  var form = document.getElementById('add-form');
64	  var input = document.querySelector('[data-testid="todo-input"]');
65	  var list = document.querySelector('[data-testid="todo-list"]');
66	
67	  function load() {
68	    try {
69	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
70	      return Array.isArray(data) ? data : [];
71	    } catch (e) {
72	      return [];
73	    }
74	  }
75	
76	  function save() {
77	    try {
78	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
79	    } catch (e) {}
80	  }
81	
82	  function newId() {
83	    if (window.crypto && typeof crypto.randomUUID === 'function') {
84	      return crypto.randomUUID();
85	    }
86	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
87	  }
88	
89	  function render() {
90	    list.textContent = '';
91	    todos.forEach(function (todo) {
92	      var li = document.createElement('li');
93	      li.setAttribute('data-testid', 'todo-item');
94	      li.dataset.id = todo.id;
95	
96	      var text = document.createElement('span');
97	      text.setAttribute('data-testid', 'todo-text');
98	      text.textContent = todo.text;
99	
100	      var del = document.createElement('button');
101	      del.type = 'button';
102	      del.setAttribute('data-testid', 'todo-delete');
103	      del.setAttribute('aria-label', 'Delete');
104	      del.textContent = 'Delete';
105	      del.addEventListener('click', function () {
106	        todos = todos.filter(function (t) { return t.id !== todo.id; });
107	        save();
108	        render();
109	      });
110	
111	      li.appendChild(text);
112	      li.appendChild(del);
113	      list.appendChild(li);
114	    });
115	  }
116	
117	  var todos = load();
118	
119	  form.addEventListener('submit', function (event) {
120	    event.preventDefault();
121	    var text = input.value.trim();
122	    if (!text) return;
123	    todos.push({ id: newId(), text: text, createdAt: Date.now() });
124	    save();
125	    render();
126	    input.value = '';
127	    input.focus();
128	  });
129	
130	  render();
131	})();
132	</script>
133	</body>
134	</html>
